-- EasySport: 70 địa điểm từ CSV. Điểm/lượt đánh giá là dữ liệu demo. Giá theo buổi là giá tham khảo.
-- Khi nhập lại, giữ ảnh và đánh giá hiện tại. Khoảng cách phụ thuộc vị trí người dùng.
SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE
  name = VALUES(name),
  address = VALUES(address),
  latitude = VALUES(latitude),
  longitude = VALUES(longitude),
  sport_type = VALUES(sport_type),
  indoor = VALUES(indoor),
  price_per_hour = VALUES(price_per_hour),
  morning_price = VALUES(morning_price),
  afternoon_price = VALUES(afternoon_price),
  evening_price = VALUES(evening_price);
COMMIT;
